import java.util.*;

class Solution {
    public ListNode reorderList(ListNode head) {
        ListNode slow = head, fast = head;
        while (fast.next != null && fast.next.next != null) {
            slow = slow.next;
            fast = fast.next.next;
        }
        ListNode second = slow.next, prev = null;
        slow.next = null;                  // end the first half
        while (second != null) {           // reverse the second half
            ListNode nxt = second.next;
            second.next = prev;
            prev = second;
            second = nxt;
        }
        ListNode p = head, q = prev;
        while (q != null) {                // weave front, back, front, back
            ListNode pn = p.next, qn = q.next;
            p.next = q;
            q.next = pn;
            p = pn;
            q = qn;
        }
        return head;
    }
}
